    "Nếu bạn cắt dọc hoặc cắt hẹp 1 phần khung hình: chọn": "세로 또는 좁은 영역을 자른 경우:",
    "để máy tự ép giãn về chuẩn full-screen 100%, hoặc chọn": "을(를) 선택하면 100% 전체 화면으로 늘어나며,",
    "để giữ đúng kích thước bạn đã chọn (phần trống xung quanh là khoảng đen).": "을(를) 선택하면 선택한 실제 크기를 유지합니다(주변 여백은 검은색으로 표시).",
    "Có (Lưu ý ảnh có thể bị méo do máy tự căn chỉnh nhé)": "예 (참고: 화면을 꽉 채우기 위해 비율이 늘어날 수 있습니다)",
    "(Ở lựa chọn": "(선택 시:",
    ": khung hình crop hiện lên đúng với kích thước đã chọn, phần trống còn lại là khoảng đen.)": ": 자른 영역이 선택한 크기 그대로 표시되며 나머지 여백은 검은색으로 채워집니다.)",
