    "Tỷ lệ tương phản nền & lớp kính chữ đang cân bằng, hiển thị mượt trên cả 6 Tab.": "배경 대비와 텍스트 유리창 투명도가 균형을 이루어 6개 탭 모두에서 선명하게 표시됩니다.",
    "Độ sáng video đang cao và lớp phủ tối rất thấp — nên kéo \"Độ tối phủ nền\" lên 20%–40% để chữ luôn dễ đọc.": "비디오 밝기가 높고 어두운 오버레이가 너무 낮습니다 — 가독성을 위해 \"배경 어둡기\"를 20%–40%로 올리는 것이 좋습니다.",
    "Thẻ chữ đang rất trong suốt trên video rõ nét — có thể tăng nhẹ \"Độ nhòe\" (4–8px) nếu thấy rối mắt.": "선명한 비디오 위에서 텍스트 카드가 매우 투명합니다 — 눈이 피로할 경우 \"흐림 효과\"(4–8px)를 약간 높여보세요.",
    "Nền đang khá tối và mờ — hãy kéo \"Độ rõ video\" lên ~80% để cảm nhận chuyển động khung cảnh tốt hơn.": "배경이 다소 어둡고 흐릿합니다 — 생동감 있는 배경을 원하시면 \"비디오 선명도\"를 약 80%로 높여보세요.",
    "🖼️ Đang phát trong cửa sổ nổi (PiP) — đóng cửa sổ nổi để xem tiếp tại đây": "🖼️ 시스템 PIP 모드로 재생 중 — 플로팅 창을 닫으면 여기에서 계속 시청할 수 있습니다",
