    "Tính năng này cần liên kết Gemini API Key tại màn hình chính.": "이 기능을 사용하려면 메인 화면에서 Gemini API 키를 연결해야 합니다.",
    "Tính năng này liên quan tới lưu trữ & thư mục làm việc thật trên thiết bị.": "이 기능은 기기의 실제 파일 저장소 및 로컬 작업 폴더와 연동됩니다.",
