    "Xuất gói chia sẻ dữ liệu dự án": "프로젝트 공유 번들 내보내기",
    "Gửi câu hỏi tự do tới Chatbot Bi Số 8": "챗봇 비 8호에게 자유 질문 보내기",
    "Lưu cấu hình System Prompt hệ thống": "시스템 프롬프트 설정 저장",
    "Đặt lại & lưu System Prompt hệ thống": "기본 시스템 프롬프트 초기화 및 저장",
    "Xóa chương khỏi kho lưu trữ": "저장소에서 챕터 삭제",
    "# HỒ SƠ KHUNG STORY BIBLE — THỂ LOẠI TRINH THÁM NOIR / BÍ ẨN": "# 스토리 바이블 구조 프레임 — 느와르 추리 / 미스터리 장르",
    "- Bối cảnh trung tâm: Tháp Đồng Hồ Đêm Mưa & Thành phố Cảng Sương Mù.": "- 중심 배경: 비 내리는 밤의 시계탑 & 안개 낀 항구 도시.",
    "- Quy luật thời gian: Chuông đồng chỉ rung khi có sự cố chuyển giao ký ức hoặc mở khóa tầng áp mái.": "- 시간 규칙: 청동 종은 기억 동기화 이상이 발생하거나 다락방 잠금이 해제될 때만 울린다.",
    "- Giọng văn chủ đạo: Noir tiết chế, giàu chi tiết giác quan (mưa, đồng thau, giấy da, ánh đèn bão).": "- 핵심 문체: 절제된 느와르 톤, 풍부한 오감 묘사(빗소리, 황동, 양피지, 폭풍 랜턴 불빛).",
    "=== TỔNG HỢP STORY BIBLE CHÍNH THỨC (BẢN MẪU GUEST MODE) ===": "=== 공식 스토리 바이블 종합 (게스트 모드 샘플) ===",
    "1. Bối cảnh & Luật ngầm:": "1. 세계관 배경 및 숨겨진 규칙:",
    "- Vụ hỏa hoạn 20 năm trước thực chất là màn che đậy cho cuộc thử nghiệm lưu trữ ký ức của Giáo sư Hoàng tại Tháp Đồng Hồ.": "- 20년 전 화재 사건은 사실 시계탑에서 진행된 황 교수의 기억 보존 실험을 은폐하기 위한 위장이었다.",
    "- Con số 13:00 trên mặt đồng hồ không chỉ thời gian mà là mã khóa cơ học nối lên gác chuông.": "- 시계판의 13:00은 단순한 시각이 아니라 종탑 다락방으로 연결되는 기계식 암호다.",
    "2. Tuyến nhân vật chính:": "2. 주요 등장인물 라인업:",
    "- Trần Minh Khôi (Chính): Thám tử lưu trữ, có vết sẹo cũ ở cổ tay trái, luôn giữ đồng hồ quả quýt vỡ kính.": "- 쩐 민 코이 (주인공): 기록보관소 탐정, 왼쪽 손목에 오래된 흉터가 있으며 유리가 깨진 회중시계를 지니고 다닌다.",
    "- Lệ Băng (Đồng hành / Nghi phạm): Người giữ chùm chìa khóa đồng La Mã, nắm nửa sự thật về vụ hỏa hoạn.": "- 레 방 (동행 / 용의자): 로마 숫자가 새겨진 청동 열쇠 꾸러미의 파수꾼으로 화재 사건의 진실 절반을 쥐고 있다.",
    "- Bé Miu (Nhân chứng bí ẩn): Xuất hiện trong hầm kín dù cửa khóa ngoài, cầm mảnh đồng khắc tên Giáo sư Hoàng.": "- 꼬마 미우 (신비한 목격자): 밖에서 잠긴 지하실에 홀연히 나타나 황 교수의 이름이 새겨진 구리 조각을 건넨다.",
    "- Giáo sư Hoàng (Phản diện giấu mặt): Tác giả chuỗi sổ cái bìa đen và cỗ máy đồng bộ xung chuông.": "- 황 교수 (숨겨진 적대자): 검은 표지 장부 6권과 종소리 펄스 기억 동기화 장치를 만든 장본인.",
    "3. Mạch phục bút đang chạy:": "3. 진행 중인 복선 라인:",
    "- Chìa khóa thứ tư hình bán nguyệt úp ngược -> Mở két sắt tầng áp mái.": "- 뒤집힌 반달 문양이 새겨진 네 번째 열쇠 -> 다락방 금고 개방.",
    "- Vết thương cổ tay trái của Minh Khôi cộng hưởng với tần số chuông đồng.": "- 민 코이의 왼쪽 손목 상처가 청동 종의 진동 주파수와 공명한다.",
    "Nhân vật chính (Thám tử lưu trữ)": "주인공 (기록보관소 탐정)",
    "Điềm tĩnh, quan sát tỉ mỉ chi tiết cơ học, ám ảnh công lý bị chôn vùi.": "침착하고 기계적 세부 구조를 면밀히 관찰하며 묻혀버린 정의에 집착한다.",
    "Ngắn gọn, sắc bén, dùng ngôi \"Tôi\" — gọi Lệ Băng bằng chức danh hoặc tên.": "간결하고 날카로우며 1인칭 '나'를 사용 — 레 방을 직함이나 이름으로 부른다.",
    "Người giữ khóa Tháp Đồng Hồ": "시계탑 열쇠지기",
    "Lạnh lùng bên ngoài nhưng cố bảo vệ bằng chứng gốc trước thế lực giấu mặt.": "겉으로는 차갑지만 배후 세력으로부터 원본 증거를 끝까지 지키려 한다.",
    "Mỉa mai nhẹ, hay đặt câu hỏi ngược để dò thái độ.": "가벼운 빈정거림이 섞여 있으며 상대의 태도를 떠보기 위해 자주 반문한다.",
    "Nhân chứng bí ẩn": "신비한 목격자",
    "Nhạy bén với âm thanh bánh răng, xuất hiện tại những nơi tưởng chừng kín bưng.": "톱니바퀴 소리에 민감하며 완전히 밀폐된 듯한 공간에 신기하게 나타난다.",
    "Ngây thơ nhưng câu nào cũng chứa ẩn ý cảnh báo.": "천진난만한 말투지만 모든 문장에 경고의 복선이 담겨 있다.",
    "Phản diện giấu mặt": "숨겨진 흑막",
    "Lập dị, tôn sùng việc \"khắc thời gian vào đồng thau\".": "괴짜 같은 성격으로 '황동 속에 시간을 새기는 것'을 숭배한다.",
    "Trang trọng, học thuật qua các trang sổ cái để lại.": "남겨진 장부 페이지마다 격식 있고 학술적인 어조가 배어 있다.",
    "13:00 là mã khóa gác chuông chứ không phải giờ cháy": "13:00은 화재 시각이 아니라 종탑 다락방 암호다",
    "Lệ Băng, Giáo sư Hoàng (Minh Khôi chỉ mới suy ra ở Chương 3)": "레 방, 황 교수 (민 코이는 3장에서야 추리해 냄)",
    "Giới cảnh sát thành phố & nhân viên viện lưu trữ": "시 경찰국 및 기록보관소 직원들",
    "Đường thông gió bí mật sau giá sách tầng hầm nối thẳng xuống bờ sông": "지하실 책장 뒤 비밀 환기구가 강변으로 곧장 연결됨",
    "Trần Minh Khôi và Lệ Băng": "쩐 민 코이와 레 방",
    "Vết sẹo cổ tay trái của Minh Khôi là dấu tích của chiếc vòng đồng thử nghiệm đầu tiên": "민 코이의 왼쪽 손목 흉터는 첫 번째 실험용 청동 고리의 흔적이다",
    "Giáo sư Hoàng, Lệ Băng": "황 교수, 레 방",
    "Trần Minh Khôi (cấm AI để lộ quá sớm trước Chương 5!)": "쩐 민 코이 (5장 이전에 AI가 조기 누설하는 것을 엄격히 금지!)",
    "Chìa khóa thứ tư khắc vệt bán nguyệt úp ngược": "뒤집힌 반달 문양이 새겨진 네 번째 열쇠",
    "Trùng khớp mảnh giấy cháy dở tại viện lưu trữ, dùng mở két tầng áp mái.": "기록보관소에서 찾은 불탄 종이 조각과 일치하며 다락방 금고를 여는 데 사용됨.",
