    "Làm dịu ánh nền phía sau bản thảo cho phiên viết sâu sau nửa đêm.": "자정 이후의 몰입 집필을 위해 원고 뒤 배경 빛을 은은하게 낮춥니다.",
    "Kéo sang phải để hình nền/tranh nghệ thuật hiện rõ rực rỡ hơn; kéo sang trái để khung chữ đậm hơn khi đọc lâu.": "오른쪽으로 끌면 배경/아트워크가 더 선명해지고, 왼쪽으로 끌면 장시간 읽기 좋게 텍스트 창이 진해집니다.",
    "Giữ nguyên màu ảnh/video gốc độ nét cao.": "고화질 원본 사진/영상 색감을 그대로 유지합니다.",
    "Tăng chiều sâu tương phản cho ảnh phố đêm hoặc trinh thám.": "밤거리나 추리·미스터리 장면에 어울리게 대비 깊이를 높입니다.",
