    "bên dưới để tạo nhanh PDF nhị phân cho toàn bộ các chương hiện tại của Studio!": "버튼을 눌러 현재 스튜디오의 모든 챕터를 바이너리 PDF로 빠르게 생성할 수 있습니다!",
    "📕 Gộp Thành 1 File .PDF": "📕 1개의 .PDF 파일로 병합",
    "📄 Gộp Thành 1 File .TXT": "📄 1개의 .TXT 파일로 병합",
    "📦 Nén Thành .ZIP Cục Bộ": "📦 로컬 .ZIP으로 압축",
    "✂️ Tách Chương Đưa Vào Tab 2": "✂️ 챕터 분할하여 탭 2로 보내기",
    "🟢 1. CHẠY 100% BẰNG MÁY BẠN (OFFLINE / KHÔNG TỐN MẠNG)": "🟢 1. 내 기기에서 100% 실행 (오프라인 / 데이터 소모 없음)",
    "💾 Viết bản thảo, Tự lưu 3 tầng, Undo & Time-Machine": "💾 원고 집필, 3단계 자동 저장, 실행 취소 및 Time-Machine",
    "Dữ liệu nằm hoàn toàn trong RAM, localStorage, IndexedDB và thư mục ổ cứng của bạn (0 byte gửi lên server trung gian).": "데이터는 오직 RAM, localStorage, IndexedDB 및 로컬 드라이브 폴더에만 저장됩니다 (중간 서버 전송 0바이트).",
    "📅 Điểm danh 7 ngày, Huy hiệu, Pomodoro & Nhạc thiên nhiên WebAudio": "📅 7일 출석 체크, 배지, Pomodoro 및 WebAudio 자연 사운드",
    "Đồng hồ đếm ngược, tiếng mưa rơi/suối/lò sưởi tổng hợp trực tiếp bằng chip âm thanh WebAudio và chuỗi ngày viết lưu tại trình duyệt.": "카운트다운 타이머, WebAudio 엔진으로 실시간 합성되는 빗소리/시냇물/벽난로 소리, 연속 집필 기록이 브라우저에 저장됩니다.",
    "🎨 Khung trang sách, 60FPS Hình nền & Kho tranh nghệ thuật": "🎨 책 페이지 프레임, 60FPS 배경 및 아트워크 갤러리",
    "Toàn bộ hạt chuyển động Canvas 60FPS và bộ lọc ánh sáng bảo vệ mắt được GPU trình duyệt dựng ngay lập tức khi mất mạng.": "모든 Canvas 60FPS 입자 효과와 시력 보호 조명 필터는 오프라인 상태에서도 브라우저 GPU가 즉시 렌더링합니다.",
    "📦 Đóng gói .ZIP, .DOCX chuẩn OOXML, .EPUB, .TXT & Tạo/Gộp .PDF trong RAM": "📦 RAM 내에서 .ZIP, OOXML 표준 .DOCX, .EPUB, .TXT 패키징 및 .PDF 생성/병합",
    "Hoạt động theo mô hình client-side giống iLovePDF: tệp của bạn được CPU & RAM tại máy đọc, cắt ghép và tải thẳng về Downloads, không upload.": "iLovePDF와 같은 클라이언트 방식으로 작동합니다. 파일은 로컬 CPU와 RAM에서 읽고 병합한 뒤 업로드 없이 다운로드 폴더로 바로 저장됩니다.",
    "🔍 Quét sáo rỗng (Cliche), Tìm BM25 RAG & Cắt file tiểu thuyết thành chương": "🔍 클리셰(Cliche) 스캔, BM25 RAG 검색 및 소설 챕터 분할",
    "Tách hàng trăm nghìn từ thành từng chương riêng biệt vào Tab 2 hoặc tìm chi tiết cũ bằng thuật toán nội bộ chỉ trong vài mili-giây.": "내장 알고리즘으로 수십만 단어를 몇 밀리초 만에 탭 2의 개별 챕터로 분리하거나 이전 세부 설정을 찾아냅니다.",
    "🔵 2. BẮT BUỘC DÙNG INTERNET / API ĐÁM MÂY": "🔵 2. 인터넷 / 클라우드 API 필수",
    "🤖 Gọi Gemini AI (Flash-Lite, 3.8 Flash, 3.1 Pro, Argon 4, Carbon 4, Hydrogen 4)": "🤖 Gemini AI 호출 (Flash-Lite, 3.8 Flash, 3.1 Pro, Argon 4, Carbon 4, Hydrogen 4)",
    "Phải kết nối Internet để gửi prompt trực tiếp từ trình duyệt của bạn tới máy chủ API Google Generative Language bằng API Key riêng.": "개인 API Key를 사용해 브라우저에서 Google Generative Language API 서버로 프롬프트를 직접 전송하려면 인터넷 연결이 필요합니다.",
    "🏛️ Tóm tắt Story Bible bằng AI & Đối chiếu AI Diff nâng cao": "🏛️ AI 스토리 바이블 요약 및 고급 AI Diff 비교",
    "Phần phân tích ngôn ngữ chuyên sâu cần mạng gọi Gemini; khi mất mạng hệ thống vẫn tự trích xuất từ khóa cơ bản tại máy.": "심층 언어 분석은 Gemini 호출을 위해 인터넷이 필요하며, 오프라인일 때도 기본 키워드는 로컬에서 자동 추출됩니다.",
    "☁️ Tải dự án lên Google Drive (OAuth) & Mở Google NotebookLM": "☁️ Google Drive(OAuth)에 프로젝트 업로드 및 Google NotebookLM 열기",
    "Cần Internet để xác thực Google OAuth cá nhân, đồng bộ file .ZIP sang Drive hoặc làm việc trên NotebookLM đám mây.": "개인 Google OAuth 인증, .ZIP 파일의 Drive 동기화 또는 클라우드 NotebookLM 작업에는 인터넷이 필요합니다.",
    "📊 Gửi Báo Lỗi tự động về Google Sheets 2 cột (Apps Script Web App)": "📊 2열 Google Sheets로 버그 리포트 자동 전송 (Apps Script Web App)",
    "Cần mạng để gọi webhook HTTPS của Google Apps Script; nếu mất mạng, báo lỗi vẫn được cất vào hộp thư cục bộ chờ gửi sau.": "Google Apps Script HTTPS 웹훅 호출에 인터넷이 필요하며, 오프라인 시에는 로컬 발신함에 저장되었다가 나중에 전송됩니다.",
