    "Chu kỳ lưu 3 tầng hoặc mở modal kiểm tra làm mất vị trí con trỏ văn bản đang gõ.": "3단계 저장 주기나 검사 모달 열기로 인해 입력 중이던 텍스트 커서 위치가 사라집니다.",
