    "Khi tác phẩm dài hàng chục đến hàng trăm chương, AI API chạy trực tiếp để tóm tắt nhanh tại đây rất dễ bị": "작품이 수십~수백 화로 길어지면 이곳에서 AI API를 직접 호출해 빠르게 요약할 때",
