    "👅 Vị Giác": "👅 미각",
    "Tạo cảm giác điện ảnh ngay lập tức thay vì kể tính từ khô.": "건조한 형용사 나열 대신 즉각적인 영화적 몰입감을 만들어 냅니다.",
    "Căng thẳng / Che giấu bí mật": "긴장 / 비밀 숨기기",
    "↳ Chèn vào bản thảo": "↳ 원고에 삽입",
    "“Ánh đèn huỳnh quang nhấp nháy cắt ngang sống mũi hắn, hắt một vệt bóng xám dài xuống mặt bàn gỗ.”": "“깜빡이는 형광등 불빛이 그의 콧날을 가로질러 나무 탁자 위로 긴 회색 그림자를 드리웠다.”",
    "Hoảng hốt kìm nén": "억누른 당혹감",
    "“Đầu ngón tay đang giữ quai tách khẽ khựng lại, làm gợn sóng nhỏ trong lòng chén trà sậm màu.”": "“찻잔 손잡이를 쥔 손끝이 미세하게 멈칫하자, 짙은 찻물 위로 작은 파문이 일었다.”",
    "Cô độc / Lạnh lẽo đô thị": "고독 / 차가운 도시",
    "“Ánh neon từ biển hiệu đối diện rỉ qua khe rèm chớp, nhuộm xanh bệ cửa sổ ẩm sương.”": "“맞은편 간판의 네온 불빛이 블라인드 틈새로 스며들어 이슬 맺힌 창틀을 푸르게 물들였다.”",
    "Ngỡ ngàng sững sờ": "멍한 놀라움",
    "“Đồng tử mở to hơn bình thường một chút, phản chiếu nguyên vẹn ngọn lửa nhỏ đang rung trước gió.”": "“동공이 평소보다 조금 더 커지며 바람 앞에서 흔들리는 작은 불꽃을 온전히 비추었다.”",
    "Kiệt sức sau biến cố": "사건 이후의 탈진",
    "“Quầng thâm mờ dưới mi mắt khiến cái chớp mắt của cô chậm hơn bình thường nửa nhịp.”": "“눈꺼풀 아래 번진 옅은 다크서클 탓에 그녀의 눈 깜빡임이 평소보다 반 박자 느려졌다.”",
    "Cảnh giác tột độ": "극도의 경계심",
    "“Ánh nhìn quét nhanh qua khe cửa khép hờ, dừng đúng hai giây ở vệt bùn mới in cạnh thảm chùi chân.”": "“시선이 반쯤 닫힌 문틈을 빠르게 훑고, 현관 매트 옆 새로 찍힌 진흙 자국에 정확히 2초간 멈췄다.”",
    "🌦️ Bối Cảnh Thời Tiết & Ánh Sáng Điện Ảnh (Chèn Nhanh Mở Cảnh)": "🌦️ 시네마틱 날씨 및 조명 배경 (장면 도입 빠른 삽입)",
    "🌧️ Mưa đêm & Đèn đường": "🌧️ 밤비와 가로등",
    "Chèn mở cảnh": "도입 묘사 삽입",
    "Hạt mưa đập chéo vào mặt kính quán cà phê, kéo nhòe vệt đèn hậu đỏ rực bên kia đại lộ.": "빗방울이 카페 유리창을 비스듬히 두드리며 대로 건너편의 붉은 미등 불빛을 번지게 했다.",
    "🌫️ Sương sớm vùng cao / Đà Lạt": "🌫️ 고원 아침 안개 / 달랏",
    "Lớp sương trắng bàng bạc vắt ngang hàng thông, thấm lạnh qua gấu áo len ngay khi cửa vừa hé.": "은백색 안개가 소나무 숲 위로 드리워져, 문이 살짝 열리자마자 스웨터 자락 너머로 서늘함이 스며들었다.",
    "☀️ Trưa nắng gắt ngột ngạt": "☀️ 숨 막히는 한낮의 폭염",
    "Mặt đường nhựa bốc hơi nóng hập hừ, ánh nắng chói chang khiến bóng đổ dưới chân co rút thành một chấm đen sắc lẹm.": "아스팔트 도로에서 후끈한 열기가 뿜어져 나왔고, 눈부신 햇살에 발밑 그림자가 날카로운 검은 점으로 쪼그라들었다.",
    "🌃 Đêm mất điện / Ánh nến": "🌃 정전된 밤 / 촛불",
    "Bóng trần nhà rung rinh theo ngọn bấc đèn cầy mỗi lần có luồng gió lùa qua khe cửa gỗ mục.": "썩은 나무 문틈으로 바람이 스며들 때마다 천장의 그림자가 촛불 심지를 따라 흔들렸다.",
    "🍂 Gió thu cuối chiều": "🍂 늦은 오후의 가을바람",
    "Cơn gió se sắt cuốn theo mùi hoa sữa hăng hắc và tiếng lá khô lạo xạo lăn qua bậc thềm đá.": "서늘한 바람이 알스토니아 꽃의 알싸한 향기와 돌계단을 구르는 마른 나뭇잎의 바스락거리는 소리를 실어 왔다.",
    "📡 Cảm biến 5 giác quan chương đang viết:": "📡 집필 중인 챕터 5감 센서:",
