    "Mưa đêm vẫn rơi đều trên mái hiên cổ kính, phản chiếu ánh đèn vàng ấm áp xuống mặt đường lát đá ướt đẫm.": "밤비는 고풍스러운 처마 위로 변함없이 내리며, 비에 흠뻑 젖은 돌길 위로 따뜻한 노란 불빛을 비추고 있었다.",
