    "Giải đáp chi tiết cách dùng 6 Màn hình, Duyệt màu Google Docs, Biểu đồ Chế độ 5, Phiên bản Tab 6 và Xuất PDF chọn Font!": "6개 화면, Google Docs 스타일 색상 검토, 모드 5 차트, Tab 6 버전 관리 및 글꼴 선택 PDF 내보내기 사용법을 자세히 안내합니다!",
