    "Cổng Kết Nối & Nút Ủng Hộ Đăng • Entry Gate & Creator Bar": "연결 게이트 & Đăng 후원 버튼 • Entry Gate & Creator Bar",
    "CỔNG KẾT NỐI · TẢI APP PWA · MOD 01-05 · MOD 29-30": "연결 게이트 · PWA 앱 다운로드 · MOD 01-05 · MOD 29-30",
    "🇻🇳 Chào mừng bạn tới Bi's Novel Writing Studio với bộ biểu tượng chân dung mới! Ngay đầu cổng là nút Mai Hải Đăng (Bi), nút to Ủng hộ Đăng và nút Tải App về thiết bị ngay.": "🇻🇳 새로운 초상화 아이콘 세트가 적용된 Bi 소설 집필 스튜디오에 오신 것을 환영합니다! 게이트 맨 위에는 Mai Hải Đăng (Bi) 버튼, 큰 Đăng 후원하기 버튼, 기기에 바로 앱 설치 버튼이 있습니다.",
