    "\"Mình lấy cảm hứng từ nỗi đau không có web riêng, mình thì không biết lập trình nên là mình làm hơi lâu, cụ thể là 3 ngày với AI, mong mọi người thông cảm nếu có sai sót nha, có gì cứ report bug cho m": "\"나만의 집필 웹사이트가 없다는 불편함에서 영감을 얻었습니다. 코딩을 몰라서 조금 오래 걸렸는데, 정확히 AI와 함께 3일이 걸렸어요. 혹시 부족한 점이 있더라도 너그럽게 양해해 주시고, 문제가 있으면 언제든 버그 제보해 주세요!\"",
