    "Ít nhất 1 chương đã được Approve & Lock Draft và đồng bộ vào hệ thống Story Bible.": "최소 1개 챕터가 Approve & Lock Draft를 거쳐 스토리 바이블 시스템에 동기화되었습니다.",
    "Yêu cầu: 1,500 từ · 1 chương đã duyệt": "요구 조건: 1,500단어 · 승인된 챕터 1개",
    "🖋️ Nhịp Bút Bền Bỉ": "🖋️ 꾸준한 필력",
    "Vượt mốc 10.000 từ với 3 chương hoàn chỉnh — tương đương hồi mở màn của một bộ Light Novel thực thụ.": "완성된 3개 챕터로 10,000단어 돌파 — 정식 라이트 노벨의 도입부 분량에 해당합니다.",
    "Yêu cầu: 10,000 từ · 3 chương đã duyệt": "요구 조건: 10,000단어 · 승인된 챕터 3개",
    "🏛️ Kiến Trúc Sư Thế Giới": "🏛️ 세계관 건축가",
    "Trên 30.000 từ — lúc này Story Bible, Ma trận Ai Biết Gì và Phục bút đã phát huy tối đa uy lực.": "30,000단어 이상 — 이 시점부터 스토리 바이블, 정보 인지 매트릭스, 복선이 최대 위력을 발휘합니다.",
    "Yêu cầu: 30,000 từ · 6 chương đã duyệt": "요구 조건: 30,000단어 · 승인된 챕터 6개",
    "👑 Chủ Nhân Quyển Một": "👑 1권의 주인",
    "Đạt dung lượng 1 quyển Light Novel hoàn chỉnh! Hãy dùng Tab 6 xuất sách DOCX / PDF lưu giữ thành quả.": "라이트 노벨 한 권 분량을 완성했습니다! Tab 6에서 DOCX / PDF로 출판해 소중한 결실을 간직하세요.",
    "Yêu cầu: 60,000 từ · 10 chương đã duyệt": "요구 조건: 60,000단어 · 승인된 챕터 10개",
    "🌌 Đại Tự Sự Vượt Mọi Giới Hạn": "🌌 한계를 뛰어넘은 대서사시",
    "Hơn 120.000 từ — Mai Hải Đăng xin gửi lời chúc mừng nồng nhiệt nhất tới sự kiên trì phi thường của bạn!": "120,000단어 돌파 — Mai Hải Đăng이 작가님의 경이로운 끈기에 가장 뜨거운 축하를 보냅니다!",
    "Yêu cầu: 120,000 từ · 20 chương đã duyệt": "요구 조건: 120,000단어 · 승인된 챕터 20개",
