    "1. Bấm nút \"🔄 Reload Lại Web Để Kết Nối\" bên dưới để quay về màn hình chính.": "1. 아래의 \"🔄 웹 새로고침 후 연결\" 버튼을 눌러 메인 화면으로 돌아가세요.",
    "2. Lấy miễn phí rồi sao chép & dán Gemini API Key tại Bước 1 (Google AI Studio).": "2. Google AI Studio에서 무료로 Gemini API Key를 발급받아 1단계에 복사해 붙여넣으세요.",
    "3. Chọn Thư mục làm việc trên máy tính / điện thoại tại Bước 2 — mọi dữ liệu của bạn sẽ được lưu an toàn 100%!": "3. 2단계에서 PC 또는 휴대폰의 작업 폴더를 선택하세요 — 모든 데이터가 100% 안전하게 저장됩니다!",
