    "⚠️ Hãy chọn một phiên bản trong danh sách trước khi khôi phục.": "⚠️ 복원하기 전에 목록에서 버전을 먼저 선택해 주세요.",
    "🗑️ Đã xóa mốc phiên bản khỏi danh sách.": "🗑️ 목록에서 해당 버전 마일스톤을 삭제했습니다.",
