    "📄 Đã tải xuống Nhật ký Phiên bản Markdown!": "📄 Markdown 버전 로그를 다운로드했습니다!",
    "⚠️ Cửa sổ đầu ra AI đang trống, chưa có nội dung để đưa vào bản thảo!": "⚠️ AI 출력 창이 비어 있어 원고에 넣을 내용이 없습니다!",
    "⚠️ Đang khởi tạo trình quản lý chương, vui lòng thử lại.": "⚠️ 챕터 관리자를 초기화하는 중입니다. 잠시 후 다시 시도해 주세요.",
    "⚠️ Không tìm thấy đoạn văn hợp lệ trong đầu ra AI.": "⚠️ AI 출력에서 유효한 문단을 찾지 못했습니다.",
    "📌 Đã gắn ghi chú biên tập vào đoạn văn!": "📌 문단에 편집 메모를 달았습니다!",
    "↩️ Không còn thao tác duyệt đoạn nào để hoàn tác.": "↩️ 실행 취소할 문단 검수 작업이 더 이상 없습니다.",
    "↩️ Đã khôi phục lại đoạn văn vừa thao tác!": "↩️ 방금 작업한 문단을 되돌렸습니다!",
    "✓ Đã chấp nhận đoạn văn AI vào bản thảo chính thức!": "✓ AI 문단을 공식 원고에 수락 반영했습니다!",
    "✕ Đã từ chối và loại bỏ đoạn văn AI đó khỏi bản thảo.": "✕ 해당 AI 문단을 거절하고 원고에서 제거했습니다.",
    "✏️ Đã cập nhật và chấp nhận đoạn văn vừa sửa!": "✏️ 수정한 문단을 업데이트하고 수락했습니다!",
    "⚠️ Đoạn văn này chỉ có 1 câu nên không thể tách nhỏ hơn.": "⚠️ 이 문단은 문장이 1개뿐이어서 더 작게 나눌 수 없습니다.",
    "💬 Câu thoại trong đoạn này đã ở định dạng chuẩn!": "💬 이 문단의 대사는 이미 표준 서식에 맞춰져 있습니다!",
    "🧹 Đã chuẩn hóa câu thoại về định dạng \"- Câu thoại (Tên nhân vật)\"!": "🧹 대사를 \"- 대사 내용 (인물명)\" 형식으로 표준화했습니다!",
    "✅ Đã chấp nhận toàn bộ đoạn văn AI bổ sung vào bản thảo chính thức!": "✅ 추가된 모든 AI 문단을 공식 원고에 수락 반영했습니다!",
    "↩️ Đã từ chối toàn bộ phần AI vừa thêm và hoàn nguyên bản thảo gốc của bạn!": "↩️ 새로 추가된 AI 부분을 모두 거절하고 원래 원고로 되돌렸습니다!",
    "📋 Đã sao chép câu lệnh Story Bible chi tiết! Hãy tải PDF gộp lên NotebookLM rồi dán câu lệnh này nhé.": "📋 상세한 스토리 바이블 프롬프트를 복사했습니다! 통합 PDF를 NotebookLM에 올린 뒤 이 프롬프트를 붙여 넣으세요.",
    "⚠️ Ô \"2. Nội dung Story Bible chính thức\" hiện chưa có đủ nội dung để bóc tách.": "⚠️ \"2. 공식 스토리 바이블 내용\" 입력란에 추출할 만큼 충분한 내용이 아직 없습니다.",
    "🔒 Khung Cấu Trúc đang khóa! Hãy bấm mở khóa trước khi đổi sang mẫu thể loại mới.": "🔒 구조 틀이 잠겨 있습니다! 새 장르 템플릿으로 바꾸기 전에 먼저 잠금을 해제해 주세요.",
    "⚠️ Bản thảo chương đang mở hiện chưa có nội dung để quét nhân vật.": "⚠️ 현재 열린 챕터 초안에 인물을 스캔할 내용이 아직 없습니다.",
    "✅ Tất cả nhân vật có câu thoại trong chương này đều đã nằm trong Hồ Sơ Nhân Vật!": "✅ 이 챕터에서 대사가 있는 모든 인물이 이미 인물 프로필에 등록되어 있습니다!",
    "⚠️ Chương hiện tại đang trống, chưa có nội dung để kiểm toán.": "⚠️ 현재 챕터가 비어 있어 점검할 내용이 없습니다.",
    "🛡️ Kiểm toán hoàn tất: Không phát hiện lỗi lộ bí mật sớm hay lệch đại từ xưng hô trong chương này!": "🛡️ 점검 완료: 이 챕터에서 비밀 조기 유출이나 호칭·인칭 불일치 오류가 발견되지 않았습니다!",
    "🏛️ Đã lưu toàn bộ Story Bible, Nhân vật, Ma trận Ai Biết Gì & Phục bút (Sẵn sàng tích hợp vào Prompt Tổng)!": "🏛️ 스토리 바이블, 인물, '누가 무엇을 아는가' 매트릭스 및 복선을 모두 저장했습니다 (통합 프롬프트 반영 준비 완료)!",
    "✂️ Đã chèn phân đoạn chuyển cảnh mẫu vào Bàn viết Tab 1!": "✂️ 탭 1 집필 데스크에 샘플 장면 전환 구문을 삽입했습니다!",
    "🔀 Đã thay đổi thứ tự phân cảnh trong chương!": "🔀 챕터 내 장면 순서를 변경했습니다!",
    "📑 Đã nhân bản Mốc phân cảnh kế tiếp!": "📑 다음 장면 마커를 복제했습니다!",
    "⚠️ Chương hiện tại chưa có Mốc phân cảnh nào.": "⚠️ 현재 챕터에 장면 마커가 아직 없습니다.",
    "⚠️ Chương này chưa có Mốc phân cảnh nào để xuất.": "⚠️ 이 챕터에는 내보낼 장면 마커가 없습니다.",
    "🎬 Đã xuất Sơ đồ Phân cảnh Markdown (.MD)!": "🎬 Markdown 장면 구성표(.MD)를 내보냈습니다!",
    "⚠️ Bạn hãy nhập ít nhất Thời gian, Địa điểm hoặc Mục tiêu diễn biến của phân cảnh nhé!": "⚠️ 장면의 시간, 장소 또는 전개 목표 중 최소 한 가지는 입력해 주세요!",
    "✏️ Đã cập nhật Mốc chuyển phân cảnh!": "✏️ 장면 전환 마커를 업데이트했습니다!",
