    "Chưa có Gemini API Key. Hãy bấm nút Google AI Studio ở trên để copy key rồi dán vào đây.": "아직 Gemini API Key가 없습니다. 위의 Google AI Studio 버튼을 눌러 키를 복사한 뒤 여기에 붙여넣으세요.",
    "📂 Chọn Thư Mục Làm Việc Trên Máy Tính": "📂 컴퓨터 작업 폴더 선택",
    "Chưa chọn thư mục ổ cứng (nên chọn thư mục con riêng như D:\\TruyenCuaBi để tránh trình duyệt chặn thư mục hệ thống Desktop/Documents).": "로컬 디스크 폴더가 선택되지 않았습니다 (브라우저가 Desktop/Documents 시스템 폴더를 차단하지 않도록 D:\\TruyenCuaBi 같은 별도 하위 폴더를 선택하세요).",
