    "Service Worker (sw.js) đệm toàn bộ 44 module + giao diện để mở App viết truyện kể cả khi mất mạng.": "Service Worker (sw.js)가 44개 전체 모듈과 UI를 캐싱하여 오프라인 상태에서도 집필 앱을 열 수 있습니다.",
    "Tự căn vùng tai thỏ/thanh vuốt (safe-area), ẩn thanh đáy khi mở bàn phím điện thoại và chia lưới đa cột trên Laptop.": "노치/홈 바(safe-area)를 자동 조정하고, 모바일 키보드가 열릴 때 하단 바를 숨기며, 노트북에서는 다단 그리드로 배치합니다.",
    "🧪 GUEST MODE — PROMPT MẪU 5 CHẾ ĐỘ": "🧪 GUEST MODE — 5모드 샘플 프롬프트",
    "Click bất kỳ mẫu nào bên dưới để chạy mô phỏng tức thì!": "아래 아무 샘플이나 클릭하면 즉시 시뮬레이션이 실행됩니다!",
