    "Mở Trung Tâm AI 5 Chế Độ Tab 3": "Tab 3 5모드 AI 허브 열기",
    "▾ Đủ Hệ Gemini 4 (Hydrogen / Argon / Carbon) + Pro / Flash & Tư Duy Thấp / TB / Cao / XHIGH": "▾ 전체 Gemini 4 라인업 (Hydrogen / Argon / Carbon) + Pro / Flash & 낮음 / 보통 / 높음 / XHIGH 추론",
    "Mở Chọn Mô Hình & Tư Duy Tab 3": "Tab 3 모델 및 추론 수준 선택 열기",
    "Khi cần viết chương sâu sắc hoặc kiểm toán logic nhiều tầng (chọn Gemini 4 Hydrogen + Tư duy Cao/XHIGH), viết đại tự sự (Argon 4), hoặc nháp nhanh tiết kiệm quota (Flash / Flash-Lite).": "깊이 있는 챕터 집필이나 다층 논리 감사 시(Gemini 4 Hydrogen + 높음/XHIGH 추론), 대서사 문체(Argon 4), 또는 할당량을 아끼는 빠른 초안(Flash / Flash-Lite)에 사용하세요.",
    "Trong Trung tâm điều khiển AI Tab 3, Cổng Bước 2, Chế độ 5, Tab 4 Bible hoặc Trợ lý Viên Bi Số 8, chọn mô hình mong muốn ở danh sách \"Mô hình Gemini\".": "Tab 3 AI 제어 센터, 2단계 포털, 모드 5, Tab 4 바이블 또는 8번 공 어시스턴트의 \"Gemini 모델\" 목록에서 원하는 모델을 선택하세요.",
    "Chọn tiếp mức \"Tư duy: Thấp / Trung bình / Cao / XHIGH\" để điều chỉnh chiều sâu suy luận của AI đồng bộ tới API Key.": "이어서 \"추론: 낮음 / 보통 / 높음 / XHIGH\" 수준을 선택해 API Key와 동기화된 AI 사고 깊이를 조절합니다.",
    "Nếu mô hình Pro hoặc Argon-4 bị giới hạn endpoint trên Key miễn phí, hộp thoại dự phòng hiện sẵn link copy câu lệnh & link mở thẳng \"Gemini của bạn\".": "무료 Key에서 Pro 또는 Argon-4 엔드포인트가 제한된 경우 대체 창이 열리며, 명령 복사 링크와 \"내 Gemini\" 직통 링크를 제공합니다.",
    "Khi mở hộp thoại dự phòng Pro/Argon-4, chỉ cần bấm chữ \"câu lệnh dưới đây\" là toàn văn Prompt Tổng Hợp tự động chép gọn vào clipboard cho bạn dán sang Gemini Web.": "Pro/Argon-4 대체 창이 열리면 \"아래 명령문\" 글자를 클릭하기만 해도 전체 통합 프롬프트가 클립보드에 깔끔하게 복사되어 Gemini Web에 바로 붙여넣을 수 있습니다.",
    "▸ Đồng Hồ Hạn Mức Ngắn Hạn (5 Giờ) & Dài Hạn (Tuần) Kèm Link Gemini Account Live": "▸ 단기(5시간) & 장기(주간) 한도 게이지 및 실시간 Gemini 계정 링크",
