    "▸ Quy Trình 2 Bước: Copy Thẳng Story Bible Vào Prompt Tổng Hợp -> Chạy Chính Thức": "▸ 2단계 워크플로우: 스토리 바이블을 통합 프롬프트에 바로 복사 -> 정식 실행",
    "Đi tới Khung Lệnh 2 Bước Tab 3": "Tab 3 2단계 명령 패널로 이동",
    "▸ Nhấn Enter Để Chạy Lệnh Nhanh Kèm Hộp Thoại Xác Nhận An Toàn (Có Tick Không Nhắc Lại)": "▸ Enter로 빠른 명령 실행 및 안전 확인 창 표시 (다시 묻지 않기 체크 지원)",
    "Thử Phím Enter Trong Khung Lệnh Tab 3": "Tab 3 명령 창에서 Enter 키 사용해 보기",
    "▸ Thông Báo Kết Quả Xong & Tự Hiện Đầu Ra Mới Nhất Ngay Trong Khung Chữ Tab 3": "▸ 완료 알림 및 Tab 3 텍스트 창에 최신 출력 결과 자동 표시",
