    "Đi tới Trạm Vẽ Biểu Đồ Mode 5": "Mode 5 다이어그램 스테이션으로 이동",
    "▸ Chèn Mốc Chuyển Phân Cảnh & Đổi Góc Nhìn (POV Switch Builder)": "▸ 장면 전환 및 시점 변경 빌더 삽입 (POV Switch Builder)",
    "Mở Bộ Tạo Mốc Chuyển Cảnh": "장면 전환 마커 생성기 열기",
