    "Đi tới nút Đồng Bộ Gemini Flash Tab 4": "Tab 4 Gemini Flash 동기화 버튼으로 이동",
    "▸ Cập Nhật Story Bible Lũy Tiến Toàn Mạch (Từ Chương 1 Tới Chương Mới Duyệt Cuối)": "▸ 전체 줄거리 누적 스토리 바이블 업데이트 (1장부터 마지막 승인 챕터까지)",
    "Xem Khung Story Bible Chính Thức Tab 4": "Tab 4 정식 스토리 바이블 창 보기",
    "▾ Cẩm Nang Chống Quên Cho Truyện Dài Hàng Trăm Chương Cùng Google NotebookLM": "▾ Google NotebookLM과 함께하는 수백 화 장편 망각 방지 가이드",
    "Đi tới Cẩm Nang NotebookLM Tab 4": "Tab 4 NotebookLM 가이드로 이동",
    "Khi tác phẩm của bạn đã vượt 15-30 chương trở lên hoặc khi bạn muốn tái tổng hợp một bộ Story Bible siêu chi tiết không sót bất kỳ manh mối nào từ đầu truyện.": "작품이 15–30장을 넘어가거나 이야기 초반의 단서 하나도 놓치지 않는 초정밀 스토리 바이블을 재구성하고 싶을 때 사용하세요.",
    "Vào Tab 4, nhìn thẻ nổi bật \"Mẹo Giữ Ký Ức Cho Truyện Dài Hàng Trăm Chương Với NotebookLM\".": "Tab 4에 들어가 강조된 \"NotebookLM으로 수백 화 장편 기억 유지 팁\" 카드를 확인하세요.",
    "Bấm nút \"1. Tải PDF Gộp Toàn Bộ Chương\" để đóng gói tất cả từ Chương 1 -> Chương cuối thành 1 bản PDF.": "\"1. 전체 챕터 병합 PDF 다운로드\"를 눌러 1장 -> 마지막 챕터까지 1개의 PDF로 묶습니다.",
    "Bấm \"2. Mở Ngay Sổ Tay NotebookLM ↗\", tải PDF vừa xuất vào đó, rồi bấm \"3. Sao Chép Prompt Tổng Hợp Story Bible Chi Tiết\" dán vào NotebookLM — nhận lại toàn văn Story Bible chuẩn mực và dán ngược vào khung Tab 4.": "\"2. NotebookLM 바로 열기 ↗\"를 눌러 방금 내보낸 PDF를 업로드하고, \"3. 상세 스토리 바이블 통합 프롬프트 복사\"를 눌러 NotebookLM에 붙여넣으세요 — 생성된 정교한 스토리 바이블 전문을 Tab 4 칸에 다시 붙여넣으면 됩니다.",
    "NotebookLM đọc cực khỏe hàng triệu chữ nguồn cùng lúc mà không bị trôi trí nhớ, cực kỳ phù hợp làm bộ nhớ dài hạn song song cùng Studio!": "NotebookLM은 수백만 단어 분량의 원문을 기억 누락 없이 한 번에 거뜬히 읽어내므로 Studio와 병행하는 장기 기억 저장소로 최적입니다!",
    "▸ Khóa Khung Cấu Trúc Story Bible (Template Frame Lock)": "▸ 스토리 바이블 구조 프레임 잠금 (Template Frame Lock)",
