    "Load your favorite MP3/WAV files from your device and set exact A-B loop points on the climax you love while writing battle or emotional scenes, or mix rain, campfire, and café sounds synthesized via zero-MB WebAudio.": "기기에서 좋아하는 MP3/WAV 파일을 불러와 전투나 감정 장면을 쓸 때 클라이맥스 구간에 정확한 A-B 반복 지점을 설정하거나, 0MB WebAudio로 합성한 빗소리·모닥불·카페 소음을 믹싱해 보세요.",
