    "Đi tới Kho Phiên Bản Time-Machine Tab 6": "Tab 6 Time-Machine 버전 보관소로 이동",
    "▾ Xuất File Word .DOCX Chuẩn OOXML ZIP Thực Thụ (Mở Mượt Trên Word & Google Docs)": "▾ 정통 OOXML ZIP 규격 Word .DOCX 내보내기 (Word 및 Google Docs에서 매끄럽게 열림)",
    "Mở Hộp Thoại Xuất .DOCX / .PDF": ".DOCX / .PDF 내보내기 대화상자 열기",
    "Khi cần tải bản thảo về máy để biên tập tiếp trong Microsoft Word, gửi cho biên tập viên nhà xuất bản hoặc tải lên Google Docs.": "Microsoft Word에서 원고를 이어 편집하거나 출판사 편집자에게 보내거나 Google Docs에 올리기 위해 기기로 내려받아야 할 때 사용합니다.",
    "Mở Hộp thoại Xuất Sách (từ Tab 6 hoặc từ thanh Công cụ biên tập ở Tab 1 / Tab 2).": "도서 내보내기 대화상자를 엽니다 (Tab 6 또는 Tab 1 / Tab 2 편집 도구 모음에서).",
    "Xác nhận 3 thông tin: Tên tác phẩm (gõ mới hoặc chọn từ danh sách đã lưu), Chương mấy (chọn từ Tab 2 hoặc toàn bộ), và Tên tác giả.": "3가지 정보를 확인하세요: 작품명(새로 입력 또는 저장 목록에서 선택), 챕터(Tab 2에서 선택 또는 전체), 작가명.",
    "Bấm nút xanh \"Xuất File .DOCX\" — file tải về có phần đầu chuẩn ZIP mở mượt trực tiếp trên mọi bộ gõ văn phòng!": "파란색 \".DOCX 파일 내보내기\" 버튼을 누르세요 — 내려받은 파일은 표준 ZIP 헤더를 갖추어 모든 오피스 프로그램에서 매끄럽게 열립니다!",
    "Header trong file Word và PDF chỉ đặt canh giữa đúng Tên Tác Phẩm, Footer chỉ đếm số trang đơn giản chứ không chèn ngày giờ rườm rà.": "Word 및 PDF 파일의 머리글에는 작품명만 가운데 정렬로 들어가고, 바닥글에는 번잡한 날짜/시간 없이 깔끔한 페이지 번호만 표시됩니다.",
    "▸ Xuất Sách .PDF Tùy Chỉnh Font/Cỡ Chữ, Bìa Sách Gói 1 Trang & NXB \"Web tiểu thuyết của Bi\"": "▸ 맞춤 글꼴/크기 .PDF 책 내보내기, 1페이지 표지 & 출판사 \"Bi 소설 집필 스튜디오\"",
