    "▸ Hệ Thống Đa Ngôn Ngữ Quốc Tế 6 Ngôn Ngữ (Tiếng Việt + 5 File JS: EN / 简体 / 繁體 / 한국어 / 日本語)": "▸ 6개 언어 국제 다국어 시스템 (베트남어 + 5개 JS 파일: EN / 简体 / 繁體 / 한국어 / 日本語)",
    "Mở Nút Đổi Ngôn Ngữ Ngay Dưới Nút Ủng Hộ Tab 6": "Tab 6 후원 버튼 바로 아래 언어 전환 버튼 열기",
    "🔍 Gõ tên tính năng cần tìm (ví dụ: NotebookLM, DOCX, PDF, nền mưa, tư duy, Bi số 8, Enter)...": "🔍 찾을 기능 이름 입력 (예: NotebookLM, DOCX, PDF, 빗방울 배경, 추론, 8번 공 Bi, Enter)...",
