    "API Key liên kết đồng bộ thời gian thực tại cả Trung tâm AI, Chat Bi Số 8, Mode 5 và tự động phát hiện 0 điểm cuối live trên tài khoản của bạn.": "연결된 API Key가 AI 허브, Bi #8 채팅, Mode 5 전체에 실시간 동기화되며, 계정에서 0개 라이브 엔드포인트를 자동 감지했습니다.",
    "🌐 Danh sách Model Gemini Live ↗": "🌐 Gemini Live 모델 목록 ↗",
