    "• 三层自动保存：0 次（上次延迟 0ms，平均 0ms） • 可用撤销/重做：0 步撤销 / 0 步重做 • 本次创作速度：0 键/分钟（1 分钟） Hãy viết thêm để hệ thống tìm ra khung giờ sáng tác sung sức nhất của bạn!": "• 3단계 자동 저장: 0회 (최근 0ms, 평균 0ms) • 실행 취소/다시 실행: 0 / 0 단계 • 현재 타자 속도: 분당 0타 (1분) 글을 더 작성하시면 시스템이 가장 몰입이 잘 되는 황금 집필 시간대를 찾아드립니다!",
    "快速扫描 AI 套话（Anti-Cliché）与段落节奏。": "AI 상투어(Anti-Cliché)와 문단 리듬을 빠르게 스캔합니다.",
    "教程视频播放器真实模拟网站的 6 个标签页与悬浮栏界面；支持直接点击任意标签页或功能节点跳转至对应秒数，并可开启自然可爱的 AI 语音讲解（Tiếng Việt / English）及双语字幕。": "안내 영상 플레이어는 웹사이트의 6개 탭과 플로팅 바 인터페이스를 그대로 재현합니다. 각 탭·기능 마커를 직접 클릭해 원하는 초로 바로 이동하고, 자연스럽고 귀여운 AI 음성 해설(베트남어 / 영어)과 이중 언어 자막을 켤 수 있습니다.",
    "Hiển thị đồng hồ sống theo thời gian thực ngay bên dưới tiêu đề \"Web viết tiểu thuyết của Bi\" trên thanh đầu trang (ví dụ: 14/11/2026 08:20:11, GMT +7 (Giờ Hà Nội)). Bấm dòng chữ đậm gạch chân bên dưới để mở/đóng cửa sổ chỉnh múi giờ quốc tế, đổi định dạng ngày giờ, xem thời tiết khu vực và đặt báo thức theo mốc giờ cụ thể với chuông hệ thống hoặc file MP3 tự chọn.": "상단 헤더 바의 \"Bi 소설 집필 스튜디오\" 제목 바로 아래에 실시간 라이브 시계를 표시합니다(예: 2026.11.14 08:20:11, GMT +7 (하노이 시간)). 아래 굵은 밑줄 문구를 클릭하면 세계 시간대 조정, 날짜/시간 형식 변경, 지역 날씨 확인 및 시스템 알람음 또는 사용자 지정 MP3 파일로 정각 알람을 설정하는 창을 열고 닫을 수 있습니다.",
    "📜 护眼米黄书纸（Nhã Nam 印刷质感）": "📜 인쇄용 미색 종이 (눈이 편안한 Nhã Nam 스타일)",
    "类书页排版写作台、一键新建章节、规范化越南语对话引号（Mod 23）、Google Docs 风格分色区块 AI 审阅（Mod 11）、五感描写、Anti-Cliché 去套路与 Lore Whisper 设定低语（Mod 24-25）。": "책 페이지 레이아웃 집필 데스크, 원탭 새 회차 생성, 베트남어 대사 따옴표 정규화(Mod 23), Google Docs 스타일 색상 블록 AI 검수(Mod 11), 오감 묘사, Anti-Cliché 및 Lore Whisper(Mod 24-25).",
    "✍️ 唯一作者：MAI HẢI ĐĂNG": "✍️ 단독 제작자: MAI HẢI ĐĂNG",
    "💖 来自 MAI HẢI ĐĂNG 的致谢": "💖 MAI HẢI ĐĂNG의 감사 인사",
    "📜 作者 MAI HẢI ĐĂNG 的设计准则": "📜 작가 MAI HẢI ĐĂNG의 설계 원칙",
