    "Khi nào mỏi mắt vì ánh sáng đêm khuya, nhớ bật bộ lọc nhiệt độ màu 3400K ở Tab 5 nhé.": "늦은 밤 화면 빛에 눈이 피로할 때는 탭 5의 3400K 색온도 필터를 켜는 걸 잊지 마세요.",
    "Mỗi góp ý Report Bug của bạn giúp trang web nhỏ này trưởng thành hơn từng ngày.": "보내 주시는 모든 버그 제보와 의견이 이 작은 스튜디오를 매일 한 걸음씩 성장시킵니다.",
    "🔒 [GUEST MODE] Không tự nhập câu lệnh tại đây — Hãy bấm chọn một Prompt Mẫu 5 Chế Độ ở khung phía trên để nạp sẵn và chạy mô phỏng ngay!": "🔒 [GUEST MODE] 여기서는 직접 명령을 입력할 수 없습니다 — 위 박스에서 5모드 샘플 프롬프트를 클릭해 바로 불러오고 시뮬레이션을 실행하세요!",
