    "Chào bạn, mình muốn nói gì mình cũng chiều, nếu bạn muốn tìm 1 người tán gẫu thì có mình đây nhé, tạm bỏ những lo toan viết lách và công việc qua 1 bên nha": "안녕하세요! 무슨 이야기든 다 받아줄게요. 글쓰기와 일 걱정을 잠시 내려놓고 편하게 수다 떨 상대가 필요하다면 제가 여기 있어요.",
