    "Bạn nên làm rõ bạn muốn AI viết mấy phân cảnh (Càng chia nhỏ càng tốt), mạch truyện nhanh hay chậm, mỗi phân cảnh bao nhiêu từ... Cơ bản như vậy cộng với cái story bible và cái cốt truyện có AI tư vấn bên cạnh nữa là mình thấy oke rồi đó bạn, mình cũng hay viết tới đó thôi hẹ hẹ": "AI가 몇 개의 장면으로 쓸지(잘게 나눌수록 좋음), 전개 속도를 빠르게 할지 느리게 할지, 각 장면을 몇 단어 정도로 쓸지 분명히 적어 주세요... 그 정도에 옆의 Story Bible 설정집과 AI 줄거리 자문만 더해지면 충분히 탄탄합니다. 저도 보통 그 정도까지만 쓰고 진행해요 ㅎㅎ",
    "Gợi ý cho Chế độ 3:": "모드 3 팁:",
    "Bạn nên đọc bản thảo trước, rồi có nghi ngờ thì đưa AI review và kiểm tra lại": "먼저 초안을 직접 한 번 읽어 보신 뒤, 의심되거나 어색한 부분이 있으면 AI에게 검토와 재확인을 맡겨 보세요.",
    "Gợi ý cho Chế độ 4:": "모드 4 팁:",
    "Thường thì mình sẽ để AI là:": "보통 저는 AI에게 이렇게 지시합니다:",
    "Bạn là 1 nhà phê bình tiểu thuyết, văn học mạng và chính quy 20 năm kinh nghiệm cho các nhà xuất bản lớn và phân tích cho tôi hướng đi cốt truyện đã tối ưu chưa, có thực sự lôi cuốn độc giả không, có chỗ nào cần cải thiện để giữ chân người đọc và khiến sức mạnh, tốc độ của cốt truyện không bị ảo quá không?": "당신은 대형 출판사의 정통 문학과 웹소설 분야에서 20년 경력을 가진 베테랑 소설 비평가입니다. 제 작품의 줄거리 전개가 최적인지, 독자를 진정으로 몰입시키는지, 독자를 붙잡아 두기 위해 개선할 부분은 어디인지, 그리고 파워 밸런스와 전개 속도가 너무 비현실적이거나 억지스럽지 않도록 다듬는 방법을 분석해 주세요.",
    "Bạn có thể copy câu mình gợi ý bằng cách bấm vào gạch chân 1 phát là xong.": "위 밑줄 친 문장을 한 번 클릭하면 추천 프롬프트가 바로 복사됩니다.",
