    "🧭 Chạy Tham Mưu Cốt Truyện (Chế Độ 2 Độc Lập)": "🧭 플롯 전략가 실행 (독립 모드 2)",
    "🔍 Chạy Kiểm Toán Logic Ngay (Chế Độ 3 Độc Lập)": "🔍 논리 감사 지금 실행 (독립 모드 3)",
    "📊 Chạy Hội Đồng Độc Giả Beta (Chế Độ 4 Độc Lập)": "📊 베타 독자 위원회 실행 (독립 모드 4)",
    "⏳ Đang gửi Prompt lên Gemini AI...": "⏳ Gemini AI에 프롬프트 전송 중...",
    "Đã tổng hợp đầy đủ khung Prompt hệ thống có sẵn + Story Bible + ngữ cảnh bản thảo + yêu cầu của bạn. Bạn có thể copy toàn bộ sang Gemini hoặc bấm Tiếp tục chạy ngay.": "사전 구성된 시스템 프롬프트 + Story Bible + 원고 문맥 + 요청 사항을 모두 결합했습니다. 전체 복사해 Gemini 웹에서 쓰거나 바로 실행할 수 있습니다.",
