    "✍️ Chế độ 1: Viết Bản Thảo Văn Học Chính Thức (Literary Drafting)": "✍️ 모드 1: 공식 문학 원고 집필 (Literary Drafting)",
    "Sáng tác văn xuôi tiểu thuyết hoàn chỉnh, giàu hình ảnh, cảm xúc chân thực, đối thoại sắc sảo và tuân thủ tuyệt đối Story Bible.": "생생한 묘사, 진정성 있는 감정, 날카로운 대사를 담아 Story Bible을 100% 준수하는 완성된 소설 본문을 집필합니다.",
    "💡 Chế độ 2: Bàn Tròn Ý Tưởng & Thiết Kế Nhánh Cốt Truyện (Plot Brainstorming)": "💡 모드 2: 아이디어 라운드테이블 & 플롯 분기 설계",
    "Đề xuất các phương án phát triển tình tiết đột phá, nút thắt bất ngờ (plot twist), cách gỡ bí kịch bản và phương án thu hồi phục bút.": "획기적인 전개 방향, 의외의 반전, 집필 막힘 해결책 및 복선 회수 방안을 제안합니다.",
    "🔍 Chế độ 3: Thanh Tra Logic, Mâu Thuẫn Thời Gian & Ma Trận Ai Biết Gì (Continuity Audit)": "🔍 모드 3: 논리 모순, 타임라인 및 인지 매트릭스 감사",
    "Rà soát nghiêm ngặt toàn bộ lỗ hổng logic, sai lệch dòng thời gian, nhân vật biết trước thông tin chưa được tiết lộ (OOC / Epistemic Leak) và phục bút bị bỏ quên.": "모든 논리 허점, 타임라인 오류, 캐릭터 OOC 및 미공개 비밀 사전 유출, 누락된 복선을 철저히 점검합니다.",
    "✨ Chế độ 4: Biên Tập Chuyên Sâu, Gọt Văn Chống Sáo Rỗng & Chuẩn Hóa Thoại (Literary Polish)": "✨ 모드 4: 심층 문학 교정, 상투어 제거 및 대사 정제",
    "Nâng cấp chất lượng văn chương của bản thảo, loại bỏ 100% từ ngữ sáo rỗng (Anti-Cliché), chuẩn hóa định dạng hội thoại và làm giàu nhạc tính tiếng Việt.": "원고의 문학성을 한층 높이고 상투어를 100% 제거하며, 대사 서식 통일 및 문장의 리듬감을 극대화합니다.",
    "🎨 Chế độ 5: Vẽ Biểu Đồ Cốt Truyện, Mạng Lưới Nhân Vật & Đối Chiếu Thời Gian (Visual Chronicle)": "🎨 모드 5: 플롯 다이어그램, 인물 관계망 & 연대기 대조",
    "Trích xuất cấu trúc sự kiện, mạng lưới quan hệ nhân vật và dòng thời gian thành sơ đồ trực quan kèm báo cáo đối chiếu xuyên chương.": "사건 구조, 인물 관계망 및 연대기를 시각화 다이어그램과 챕터 간 대조 보고서로 추출합니다.",
    "🧪 KHUYÊN DÙNG #1 · SIÊU SUY LUẬN XHIGH — CÂN BẰNG TOÀN DIỆN GEMINI 4": "🧪 1순위 추천 · 초고도 추론 XHIGH — 올라운드 GEMINI 4 밸런스",
    "⚡ Cân bằng Nhanh & Sâu (#1)": "⚡ 속도·깊이 최적 균형 (#1)",
    "Lựa chọn ưu tiên số 1 cho cả 5 chế độ: viết chương dài (Chế độ 1), tham mưu cốt truyện (Chế độ 2), kiểm toán mâu thuẫn (Chế độ 3), đánh giá độc giả (Chế độ 4) & vẽ biểu đồ (Chế độ 5).": "5가지 모드 모두를 아우르는 최우선 선택: 장편 집필(모드1), 플롯 자문(모드2), 논리 감사(모드3), 베타 비평(모드4) & 다이어그램(모드5).",
    "🌟 DÒNG FLASH MƯỢT MÀ & GIÀU CẢM XÚC": "🌟 매끄럽고 감성적인 FLASH 라인업",
    "⚡ Nhanh & Ổn định": "⚡ 빠르고 안정적",
    "Lựa chọn tối ưu nhất để viết bản thảo chính thức (Chế độ 1) và gọt văn (Chế độ 4). Văn phong có hồn, giàu ẩn dụ và không bị khô cứng.": "공식 원고 집필(모드1) 및 문장 교정(모드4)에 가장 이상적입니다. 딱딱하지 않고 생동감과 은유가 살아 있습니다.",
    "👑 CHUYÊN GIA LOGIC DÀI HƠI & PHỤC BÚT PHỨC TẠP": "👑 장편 논리 & 복합 복선 전문가",
