    "Rất mạnh khi viết các chương cao trào đan xen nhiều tuyến nhân vật, đấu trí phức tạp hoặc khi chạy Thanh tra Logic (Chế độ 3).": "다중 캐릭터 시점이 교차하는 클라이맥스, 치열한 두뇌 싸움 또는 논리 감사(모드3) 실행 시 탁월합니다.",
    "💎 ĐỈNH CAO VĂN CHƯƠNG & ĐỘC THOẠI NỘI TÂM": "💎 문학성 & 내면 독백의 정점",
    "⏳ Chậm hơn (Ưu tiên chất lượng tối đa)": "⏳ 다소 느림 (최고 품질 우선)",
    "Lý tưởng cho những phân cảnh tâm lý nặng đô, hồi tưởng bi kịch hoặc chương kết quyển cần sức nặng văn học đặc biệt.": "묵직한 심리 묘사, 비극적 회상, 혹은 남다른 문학적 무게감이 필요한 권말 챕터에 이상적입니다.",
    "⚡ SIÊU NHANH — CHỈ NÊN DÙNG ĐỂ NHÁP NHANH / HỎI ĐÁP NGẮN": "⚡ 초고속 — 빠른 메모 / 짧은 질의응답 전용 권장",
    "🚀 Tức thì": "🚀 즉각 응답",
    "⚠️ LƯU Ý: Mô hình Flash-Lite ưu tiên tốc độ nên văn phong dễ bị tóm tắt hoặc kém bay bổng. Khi viết tiểu thuyết chính thức, bạn nên đổi sang Gemini 3.8 Flash hoặc Gemini 3.1 Pro!": "⚠️ 참고: Flash-Lite 모델은 속도 우선이므로 문체가 요약되거나 건조해질 수 있습니다. 정식 소설 집필 시에는 Gemini 3.8 Flash 또는 Gemini 3.1 Pro를 권장합니다!",
    "Muốn viết sâu 20.000+ từ mỗi lần chạy với Gemini Argon 4 / Carbon 4?": "Gemini Argon 4 / Carbon 4로 한 번에 20,000자 이상 깊이 집필하고 싶으신가요?",
    "Vì 1 số lí do nên mình vẫn đang tắt kết nối Argon 4 qua API trực tiếp.": "몇 가지 이유로 현재 Argon 4의 직접 API 연결은 비활성화되어 있습니다.",
    "nếu bạn muốn viết sâu 20.000+ từ trong 1 lần chạy": "한 번의 실행으로 20,000자 이상 깊이 집필하려면",
    "hãy tích vào ô này để tự viết tiếp nối dài mạch, hoặc bấm": "이 체크박스를 선택해 자동 장편 이어쓰기를 켜거나 아래 버튼을 눌러",
    "bên dưới để copy toàn bộ prompt tổng hợp rồi dán thẳng sang Gemini Web từ": "전체 통합 프롬프트를 복사한 뒤 Gemini 웹에 바로 붙여넣어 실행하세요:",
    "Gemini Argon 4 ↗": "Gemini Argon 4 ↗",
    "Lưu ý: Tài khoản Google của bạn cần có gói Pro để dùng Argon 4, gói Ultra cho Carbon 4.": "참고: Google 계정에 Pro 요금제가 있어야 Argon 4를, Ultra 요금제가 있어야 Carbon 4를 사용할 수 있습니다.",
    "Bật chế độ tự viết tiếp nối dài mạch (20.000+ từ)": "자동 장편 이어쓰기 모드 켜기 (20,000자 이상)",
    "💎 Muốn viết sâu 20.000+ từ bằng Gemini Argon 4 / Carbon 4?": "💎 Gemini Argon 4 / Carbon 4로 20,000자 이상 깊이 쓰고 싶으신가요?",
