    "Vì 1 số lí do mà mình chưa fix bug là chưa dùng được Argon 4 qua API, nên nếu bạn muốn viết sâu 20.000+ từ trong 1 lần hãy": "기술적인 문제로 아직 API를 통한 Argon 4 연동이 지원되지 않습니다. 한 번에 20,000자 이상 깊이 작성하려면",
    ", rồi vào thẳng Gemini Web của bạn (hoặc ứng dụng nếu bạn có) và": ", Gemini 웹(또는 앱)에 바로 접속하여",
    "bấm vào đây để chạy prompt viết tiểu thuyết từ Gemini Argon 4 ↗": "여기를 클릭해 Gemini Argon 4에서 소설 작성 프롬프트를 실행하세요 ↗",
    "⚠️ Lưu ý: Bạn phải nâng cấp lên gói Pro mới dùng được Argon 4, gói Ultra cho Carbon 4 nha.": "⚠️ 참고: Pro 요금제로 업그레이드해야 Argon 4를, Ultra 요금제여야 Carbon 4를 사용할 수 있습니다.",
