    "Chế độ tách biệt đang xử lý yêu cầu chuyên môn mà không trộn lẫn với Prompt Tổng Hợp của Chế độ 1.": "독립 모드가 모드 1 마스터 프롬프트와 섞이지 않도록 요청을 별도 처리 중입니다.",
    "Vui lòng kiên nhẫn chờ, KHÔNG tắt trang web hay rời khỏi màn hình này để quá trình chạy Prompt diễn ra ổn định.": "프롬프트 실행이 안정적으로 완료되도록 창을 닫거나 이 화면을 벗어나지 말고 잠시 기다려 주세요.",
    "🎨 Đang Vẽ Biểu Đồ Cốt Truyện Từ Story Bible (Chế Độ 5)...": "🎨 Story Bible 기반 플롯 다이어그램 생성 중 (모드 5)...",
