    "Đang liên kết 100% Story Bible, Hồ sơ nhân vật, Ma trận Ai Biết Gì, Mốc chuyển phân cảnh, Ký ức BM25 và Câu lệnh của bạn. Vui lòng kiên nhẫn chờ, KHÔNG tắt trang web hay thoát khỏi màn hình này để chạy Prompt ổn định...": "Story Bible, 캐릭터 프로필, 인지 매트릭스, 장면 마커, BM25 기억과 명령을 100% 연결 중입니다. 창을 닫지 말고 기다려 주세요...",
