    "Đóng màn hình thu nhỏ": "미니 플레이어 닫기",
    "Bấm để mở ngay trình phát YouTube trong Tab 5": "클릭하여 탭 5의 YouTube 플레이어 바로 열기",
    "Thu nhỏ ra cửa sổ nổi ngoài trình duyệt / hệ điều hành (PiP)": "브라우저/시스템 플로팅 PIP 창으로 전환",
    "Bật/Tắt phát âm thanh trong nền (tắt màn hình điện thoại vẫn nghe)": "백그라운드 오디오 재생 켜기/끄기 (화면 꺼짐 유지)",
    "Điều hướng về mục YouTube ở Tab 5": "탭 5의 YouTube 영역으로 이동",
