    "🇻🇳 Sửa triệt để lỗi mất mép trên giao diện và kẹt thanh Header trên Brave/Chrome Mobile ở mọi Tab 1–6: mọi nút trên cùng luôn hiện rõ và cuộn mượt lên xuống.": "🇻🇳 Brave/Chrome 모바일의 모든 탭 1~6에서 상단 헤더와 윗부분이 잘리고 스크롤이 막히던 문제를 완전히 수정했습니다.",
