    "Tất cả popup, cửa sổ Mở to AI, bảng Cài đặt, Crop nền Video & Hỏi đáp luôn tự căn lề đỉnh khi màn hình thấp, đảm bảo nút Đóng và tiêu đề không bao giờ bị khuất!": "모든 팝업, AI 최대화 창, 설정, 배경 크롭 창이 낮은 화면에서도 상단 기준으로 안전하게 정렬되어 닫기 버튼이 가려지지 않습니다!",
    "🇻🇳 Tất cả popup, cửa sổ Mở to AI, bảng Cài đặt, Crop nền Video & Hỏi đáp luôn tự căn lề đỉnh khi màn hình thấp, đảm bảo nút Đóng và tiêu đề không bao giờ bị khuất!": "🇻🇳 모든 팝업, AI 최대화 창, 설정, 배경 크롭 창이 낮은 화면에서도 상단 기준으로 안전하게 정렬되어 닫기 버튼이 가려지지 않습니다!",
