    "Rạp video Tab 6 nay phóng to Toàn màn hình sắc nét trên cả Điện thoại dọc, Điện thoại ngang lẫn Laptop với tỷ lệ 16:9 chuẩn, phụ đề song ngữ và thanh tua đầy đủ phía dưới!": "탭 6 튜토리얼 극장은 이제 세로 모바일, 가로 모바일, 노트북 모두에서 선명한 16:9 전체 화면과 하단 이중 자막·탐색 바를 지원합니다!",
    "🇻🇳 Rạp video Tab 6 nay phóng to Toàn màn hình sắc nét trên cả Điện thoại dọc, Điện thoại ngang lẫn Laptop với tỷ lệ 16:9 chuẩn, phụ đề song ngữ và thanh tua đầy đủ phía dưới!": "🇻🇳 탭 6 튜토리얼 극장은 이제 세로 모바일, 가로 모바일, 노트북 모두에서 선명한 16:9 전체 화면과 하단 이중 자막·탐색 바를 지원합니다!",
    "v52.0 — Nối Âm Thanh YouTube ➔ MP3 Nền Mục 3, Tự Lưu 2s Toàn Diện, Cổng Gọn & Sửa Triệt Để Responsive Mobile + Fullscreen Video Tab 6": "v52.0 — YouTube ➔ 항목 3 MP3 백그라운드 연결, 2초 전면 자동 저장, 게이트 간소화 & 모바일 상단 잘림 해결 + 탭 6 전체 화면",
    "Mục 5 YouTube tự động chạy nền qua hạ tầng Mục 3 MP3 (Mod 39 & Mod 21): Hiện video ngay khi chọn, đồng bộ 2 chiều Phát/Dừng/Tua, tự ngắt tiếng bài cũ khi đổi video và hỏi xác nhận khi bật MP3 máy lúc YouTube đang chạy.": "항목 5 YouTube의 항목 3 MP3 백그라운드 연동(Mod 39 & Mod 21): 선택 즉시 영상 재생, 재생/정지/탐색 양방향 동기화, 영상 전환 시 이전 오디오 자동 종료 및 로컬 MP3 재생 시 확인 팝업 제공.",
    "Tự động lưu 3 tầng mỗi 2 giây & mọi đổi trạng thái (Mod 09/29/36): Lưu đủ từ gõ/xóa chữ, thu gọn/mở rộng các khối, tắt nhạc/video, cỡ chữ, ngôn ngữ, đồng hồ & vị trí Tab/cuộn cuối trước khi thoát.": "2초 간격 3단계 자동 저장 & 모든 UI 상태 보존(Mod 09/29/36): 글자 입력/삭제, 접기/펼치기 상태, 음악/영상 중지, 글자 크기, 언어, 시계 및 마지막 탭/스크롤 위치 저장.",
    "Cổng Kết Nối 2 bước tinh gọn & ổn định giao diện: Sửa lỗi không cuộn tới đáy trên PC, lược nút rườm rà, hết rung giật nút YouTube & hỗ trợ popup thông báo lịch từ Google Sheet (Mod 34).": "2단계 입장 게이트 간소화 & UI 안정화: PC 하단 스크롤 오류 수정, 중복 버튼 제거, YouTube 버튼 깜박임 해소 및 Google Sheet 예약 공지 팝업(Mod 34) 지원.",
    "Sửa triệt để lỗi mất mép trên (Top-Clip) Mobile ở toàn bộ 6 Tab & mọi Popup + Rạp Video Tab 6 (~12:22, 25 mốc): Tự tính tỷ lệ khung 16:9 khít màn hình Fullscreen trên cả Điện thoại dọc/ngang và Desktop.": "모바일 6개 전체 탭 및 모든 팝업 상단 잘림 완전 수정 + 탭 6 튜토리얼 극장 확장(~12:22, 25챕터): 세로/가로 모바일 및 PC에서 16:9 전체 화면 자동 맞춤.",
