    "[PHONG CÁCH BỔ TRỢ: TÌNH CẢM CÓ CHIỀU SÂU]": "[보조 장르 스타일: 밀고 당기는 심리 로맨스]",
    "[NHỊP CẢNH SLOW-BURN]: Dành thời gian cho bầu không khí thấm sâu, miêu tả chi tiết không gian vật lý, kéo dài sự dò xét giữa các nhân vật trước khi tung ra mảnh thông tin quan trọng.": "[장면 호흡 — 슬로우 번]: 분위기가 깊이 스며들도록 시간을 들이고 물리적 공간을 세밀하게 묘사하며, 핵심 정보 공개 전 인물 간 탐색전을 충분히 끌어주세요.",
    "[NHỊP CẢNH CAO TRÀO]: Tăng tốc độ chuyển động, ưu tiên câu ngắn gãy gọn, truyền tải tiếng tim đập, hơi thở dồn dập và phản xạ chớp nhoáng trong không gian hẹp.": "[장면 호흡 — 고조된 클라이맥스]: 움직임을 가속하고 짧고 강렬한 문장을 우선하며, 좁은 공간 속 심장 박동·거친 호흡·순발력 있는 반사를 생생히 전달하세요.",
    "🌟 PROMPT TỔNG HỢP CHÍNH THỨC (MASTER SYNTHESIZED NOVEL PROMPT)": "🌟 공식 통합 마스터 소설 프롬프트 (MASTER SYNTHESIZED NOVEL PROMPT)",
    "=== [PHẦN 2: THÔNG SỐ KỸ THUẬT & TIÊU CHUẨN ĐẦU RA] ===": "=== [파트 2: 기술 사양 및 출력 기준] ===",
    "- Định dạng hội thoại   : Bắt buộc dùng \"- Câu thoại (Tên nhân vật)\"": "- 대사 서식             : 반드시 \"- 대사 (캐릭터 이름)\" 형식 준수",
